library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.axi_stream_router_pkg.all;

entity arbiter is
  port (
    clk : in std_logic;
    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity arbiter;

architecture rtl of arbiter is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   type arb_state_t is (ST_IDLE, ST_ACTIVE, ST_COMPLETE);
   signal arb_state : arb_state_t := ST_IDLE;
   signal data_reg  : std_logic_vector(7 downto 0) := (others => '0');
   signal done_sig  : std_logic := '0';
   signal error_sig : std_logic := '0';
   signal status_sig: std_logic_vector(3 downto 0) := (others => '0');
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk, rst)
   begin
      if rst = '1' then
         arb_state <= ST_IDLE;
         data_reg  <= (others => '0');
         done_sig  <= '0';
         error_sig <= '0';
         status_sig<= (others => '0');
      elsif rising_edge(clk) then
         if enable_i = '1' then
            case arb_state is
               when ST_IDLE =>
                  data_reg  <= data_i;
                  arb_state <= ST_ACTIVE;
                  done_sig  <= '0';
                  error_sig <= '0';
                  status_sig<= x"1";
               when ST_ACTIVE =>
                  arb_state <= ST_COMPLETE;
                  done_sig  <= '1';
               when ST_COMPLETE =>
                  arb_state <= ST_IDLE;
                  done_sig  <= '0';
               when others =>
                  arb_state <= ST_IDLE;
            end case;
         end if;
      end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

