   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   type route_e is (ROUTE_A, ROUTE_B, ROUTE_C, ROUTE_D);
   signal route_reg : route_e := ROUTE_A;
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk, rst)
   begin
      if rst = '1' then
         route_reg <= ROUTE_A;
      elsif rising_edge(clk) then
         if enable_i = '1' then
            case data_i(7 downto 6) is
               when "00" => route_reg <= ROUTE_A;
               when "01" => route_reg <= ROUTE_B;
               when "10" => route_reg <= ROUTE_C;
               when others => route_reg <= ROUTE_D;
            end case;
         end if;
      end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

