architecture rtl of routing_decision_logic is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   type route_fsm_t is (ROUTE_IDLE, ROUTE_DECODE, ROUTE_VALID);
   signal route_fsm : route_fsm_t := ROUTE_IDLE;
   signal route_sel : std_logic_vector(1 downto 0) := "00";
   signal pkt_status : std_logic_vector(1 downto 0) := "00";
   signal pkt_done : std_logic := '0';
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk, rst)
   begin
      if rst = '1' then
         route_fsm <= ROUTE_IDLE;
         route_sel <= "00";
         pkt_status <= "00";
         pkt_done <= '0';
      elsif rising_edge(clk) then
         if enable_i = '1' then
            case data_i(7 downto 6) is
               when "00" =>
                  route_sel <= "00";
                  pkt_status <= "01";
                  pkt_done <= '1';
               when "01" =>
                  route_sel <= "01";
                  pkt_status <= "01";
                  pkt_done <= '1';
               when "10" =>
                  route_sel <= "10";
                  pkt_status <= "10";
                  pkt_done <= '1';
               when others =>
                  route_sel <= "11";
                  pkt_status <= "00";
                  pkt_done <= '1';
            end case;
            route_fsm <= ROUTE_VALID;
         else
            route_fsm <= ROUTE_IDLE;
            pkt_done <= '0';
         end if;
      end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

