architecture rtl of routing_decision_logic is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   signal route_sel_s : std_logic_vector(3 downto 0);
   signal status_s : std_logic_vector(7 downto 0);
   signal done_s : std_logic;
   signal error_s : std_logic;
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk)
   begin
      if rising_edge(clk) then
         if rst = '1' then
            route_sel_s <= (others => '0');
            status_s <= (others => '0');
            done_s <= '0';
            error_s <= '0';
         elsif enable_i = '1' then
            case data_i is
               when x"00" => route_sel_s <= "0000"; status_s <= x"01";
               when x"01" => route_sel_s <= "0001"; status_s <= x"02";
               when x"02" => route_sel_s <= "0010"; status_s <= x"04";
               when others => route_sel_s <= "1111"; status_s <= x"FF";
            end case;
            done_s <= '1';
            error_s <= '0';
         else
            done_s <= '0';
            error_s <= '0';
         end if;
      end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;
